def digest(path):
    if not path.is_file():
        return None
    h = hashlib.sha1()
    h.update(("blob %d\0" % path.stat().st_size).encode())
    with path.open("rb") as f:
        for buf in iter(lambda: f.read(1024*1024), b""):
            h.update(buf)
    return h.hexdigest()

def run(args):
    subprocess.run(args, check=True)

def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--apply", action="store_true", help="Download, verify and publish; otherwise only inspect local files")
    ap.add_argument("--site-root", default="/srv/www/severed-ember")
    ap.add_argument("--proxy", default="", help="Optional HTTP proxy URL; otherwise curl uses environment")
    ap.add_argument("--workers", type=int, default=4, choices=range(1,9))
    args = ap.parse_args()
    root = pathlib.Path(args.site_root).resolve()
    if not root.is_dir() or not (root/"index.html").is_file():
        raise SystemExit("Refusing: existing Severed Ember site root not found: "+str(root))
    pending, conflicts = [], []
    for entry in MANIFEST["files"]:
        p = root/entry["path"]
        if not p.resolve().is_relative_to(root):
            raise SystemExit("Refusing path outside site: "+str(p))
        got = digest(p)
        if got == entry["sha"]:
            continue
        if got != entry["old"]:
            conflicts.append((entry["path"], got, entry["old"]))
        else:
            pending.append(entry)
    print("Baseline:", MANIFEST["baseline"], "Target:", MANIFEST["target"], flush=True)
    print("Pending:", len(pending), "files;", sum(e["size"] for e in pending), "bytes. Already current:", len(MANIFEST["files"])-len(pending)-len(conflicts), flush=True)
    print("Historical preview files excluded:", len(MANIFEST["excluded"]), "(no live deletion)", flush=True)
    if conflicts:
        for p, found, expected in conflicts:
            print("CONFLICT", p, "found", found, "expected", expected, file=sys.stderr)
        raise SystemExit("Refusing publication: local files do not match either baseline or target; inspect conflicts first.")
    if not args.apply or not pending:
        print("Dry-run only; no network or file changes." if not args.apply else "All selected files already match target.")
        return
    for prog in ("curl","rsync","sudo"):
        if not shutil.which(prog):
            raise SystemExit("Missing required command: "+prog)
    groups={}
    for e in pending:
        groups.setdefault(e["sha"],[]).append(e)
    print("Unique blobs to download:", len(groups), "bytes:", sum(es[0]["size"] for es in groups.values()), flush=True)
    with tempfile.TemporaryDirectory(prefix="ember-delta-") as tmp:
        stage=pathlib.Path(tmp)/"site"
        stage.mkdir()
        def fetch(es):
            e=es[0]
            dest=stage/e["path"]
            dest.parent.mkdir(parents=True, exist_ok=True)
            url="https://raw.githubusercontent.com/"+MANIFEST["repository"]+"/"+MANIFEST["target"]+"/severed-ember/"+urllib.parse.quote(e["path"],safe="/")
            cmd=["curl","--fail","--location","--silent","--show-error","--retry","3","--connect-timeout","15","--max-time","180"]
            if args.proxy:
                cmd += ["--proxy",args.proxy]
            run(cmd+["--output",str(dest),url])
            if dest.stat().st_size!=e["size"] or digest(dest)!=e["sha"]:
                raise RuntimeError("Downloaded blob failed size/SHA verification: "+e["path"])
            for other in es[1:]:
                duplicate=stage/other["path"]
                duplicate.parent.mkdir(parents=True,exist_ok=True)
                shutil.copyfile(dest,duplicate)
            print("Verified:",e["path"],flush=True)
        with concurrent.futures.ThreadPoolExecutor(max_workers=args.workers) as pool:
            list(pool.map(fetch,groups.values()))
        # Re-check after download in case another deployment changed live files.
        for e in pending:
            if digest(root/e["path"]) not in (e["old"],e["sha"]):
                raise SystemExit("Live file changed during staging: "+e["path"])
            if digest(stage/e["path"])!=e["sha"]:
                raise SystemExit("Staged file failed verification: "+e["path"])
        stamp=datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%dT%H%M%SZ")
        backup=pathlib.Path("/var/backups/severed-ember")/("delta-"+stamp)
        # Preserve the list of added files for a manual rollback; never auto-delete.
        run(["sudo","mkdir","-p",str(backup)])
        rollback=pathlib.Path(tmp)/"rollback-manifest.json"
        rollback.write_text(json.dumps({"target":MANIFEST["target"],"root":str(root),"files":pending},ensure_ascii=False,indent=2),encoding="utf-8")
        run(["sudo","cp",str(rollback),str(backup/"manifest.json")])
        # Publish non-entrypoint files first, then the two public entrypoints last.
        names=[e["path"] for e in pending]
        entrypoints={"index.html","index-20261127-unit-order-v21.html"}
        for chunk in ([n for n in names if n not in entrypoints],[n for n in names if n in entrypoints]):
            if not chunk:
                continue
            listing=pathlib.Path(tmp)/"files-list"
            listing.write_bytes(b"".join(n.encode("utf-8")+b"\0" for n in chunk))
            run(["sudo","rsync","-a","--no-owner","--no-group","--from0","--files-from="+str(listing),"--backup","--backup-dir="+str(backup/"previous"),"--delay-updates",str(stage)+"/",str(root)+"/"])
        bad=[e["path"] for e in MANIFEST["files"] if digest(root/e["path"])!=e["sha"]]
        if bad:
            raise SystemExit("Post-publish verification failed: "+", ".join(bad)+"; backup: "+str(backup))
        print("Verified all selected files:",len(MANIFEST["files"]),flush=True)
        print("Published content revision:",MANIFEST["target"],flush=True)
        print("Backup and rollback manifest:",backup,flush=True)
        print("No repository pull, deletions, service restart or server configuration changes. Verify public HTTP separately.",flush=True)

if __name__=="__main__":
    main()
